import openpyxl, os

wb = openpyxl.load_workbook(os.environ['OUT_XLSX'])
ws = wb.active

# Agent Categories: rows 4-9, cols F-N (Cat1-Cat9)
agents = []
cat_assignments = []  # list of dicts: agent -> {cat_col: 1}
for r in range(4, 10):
    agent_name = ws.cell(row=r, column=5).value
    if agent_name is None:
        continue
    cats = {}
    for c in range(6, 15):  # F=6 to N=14
        v = ws.cell(row=r, column=c).value
        if v == 1:
            cats[c] = 1
    agents.append(agent_name)
    cat_assignments.append(cats)

# Agent Schedule: rows 13-18, cols F-AE
schedule = []  # list of dicts: agent -> {time_col: 1}
for r in range(13, 19):
    agent_name = ws.cell(row=r, column=5).value
    if agent_name is None:
        continue
    sched = {}
    for c in range(6, 32):  # F=6 to AE=31
        v = ws.cell(row=r, column=c).value
        if v == 1:
            sched[c] = 1
    schedule.append(sched)

# Result table: rows 22-29 (Cat1-Cat8), cols F-AE
# Row 22 = Category 1 (col F=6), Row 23 = Category 2 (col G=7), etc.
for row_idx in range(22, 30):
    cat_col = row_idx - 22 + 6  # Cat1->F(6), Cat2->G(7), ..., Cat8->M(13)
    for time_col in range(6, 32):  # F to AE
        count = 0
        for i in range(len(agents)):
            if cat_col in cat_assignments[i] and time_col in schedule[i]:
                count += 1
        ws.cell(row=row_idx, column=time_col).value = count

wb.save(os.environ['OUT_XLSX'])
print('Done. Verifying:')
for r in range(22, 30):
    vals = [ws.cell(row=r, column=c).value for c in range(6, 32)]
    print(f'Row {r} ({ws.cell(row=r, column=5).value}): {vals}')
